add_filter(
    'manage_edit-wpbp_book_columns',
    static function ( $columns ) {
        $reordered = array();

        foreach ( $columns as $key => $label ) {
            if ( 'date' === $key ) {
                $reordered['wpbp_rating'] = 'Rating';
            }
            $reordered[ $key ] = $label;
        }

        if ( ! isset( $reordered['wpbp_rating'] ) ) {
            $reordered['wpbp_rating'] = 'Rating';
        }

        return $reordered;
    }
);

add_action(
    'manage_wpbp_book_posts_custom_column',
    static function ( $column, $post_id ) {
        if ( 'wpbp_rating' === $column ) {
            echo esc_html( get_post_meta( $post_id, 'wpbp_rating', true ) );
        }
    },
    10,
    2
);

add_filter(
    'manage_edit-wpbp_book_sortable_columns',
    static function ( $columns ) {
        $columns['wpbp_rating'] = 'wpbp_rating';

        return $columns;
    }
);

add_action(
    'pre_get_posts',
    static function ( $query ) {
        if ( ! is_admin() || ! $query->is_main_query() ) {
            return;
        }

        if ( 'wpbp_book' !== $query->get( 'post_type' ) || 'wpbp_rating' !== $query->get( 'orderby' ) ) {
            return;
        }

        $query->set( 'meta_key', 'wpbp_rating' );
        $query->set( 'orderby', 'meta_value_num' );
    }
);

add_action(
    'admin_menu',
    static function () {
        add_menu_page( 'WPBP Tools', 'WPBP Tools', 'edit_posts', 'wpbp-tools', '__return_null' );
        add_submenu_page( 'wpbp-tools', 'Reports', 'Reports', 'edit_posts', 'wpbp-reports', '__return_null' );
        add_submenu_page( 'wpbp-tools', 'Settings', 'Settings', 'manage_options', 'wpbp-settings', '__return_null' );
    }
);

add_action(
    'admin_init',
    static function () {
        register_setting(
            'wpbp_settings',
            'wpbp_retention_days',
            array(
                'type'              => 'integer',
                'default'           => 30,
                'sanitize_callback' => static function ( $value ) {
                    if ( is_numeric( $value ) && (string) (int) $value === (string) $value && (int) $value >= 1 && (int) $value <= 90 ) {
                        return (int) $value;
                    }

                    add_settings_error(
                        'wpbp_retention_days',
                        'wpbp_retention_invalid',
                        'Retention must be a whole number of days between 1 and 90.',
                        'error'
                    );

                    return (int) get_option( 'wpbp_retention_days' );
                },
            )
        );
    }
);

add_action(
    'wp_ajax_wpbp_toggle_featured',
    static function () {
        check_ajax_referer( 'wpbp_toggle' );

        $post_id = isset( $_POST['post_id'] ) ? (int) $_POST['post_id'] : 0;

        if ( ! $post_id || ! current_user_can( 'edit_post', $post_id ) ) {
            wp_send_json_error( array( 'message' => 'Not allowed.' ), 403 );
        }

        $featured = ! get_post_meta( $post_id, 'wpbp_featured', true );

        if ( $featured ) {
            update_post_meta( $post_id, 'wpbp_featured', '1' );
        } else {
            delete_post_meta( $post_id, 'wpbp_featured' );
        }

        wp_send_json_success( array( 'featured' => $featured ) );
    }
);

add_action(
    'add_meta_boxes',
    static function ( $post_type ) {
        if ( 'wpbp_book' !== $post_type ) {
            return;
        }

        add_meta_box(
            'wpbp-isbn',
            'ISBN',
            static function ( $post ) {
                wp_nonce_field( 'wpbp_isbn_save', 'wpbp_isbn_nonce' );
                printf(
                    '<input type="text" name="wpbp_isbn" value="%s" />',
                    esc_attr( get_post_meta( $post->ID, '_wpbp_isbn', true ) )
                );
            },
            'wpbp_book',
            'side'
        );
    }
);

add_action(
    'save_post_wpbp_book',
    static function ( $post_id ) {
        if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
            return;
        }

        if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
            return;
        }

        if ( ! isset( $_POST['wpbp_isbn_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['wpbp_isbn_nonce'] ) ), 'wpbp_isbn_save' ) ) {
            return;
        }

        if ( ! current_user_can( 'edit_post', $post_id ) ) {
            return;
        }

        if ( ! isset( $_POST['wpbp_isbn'] ) ) {
            return;
        }

        update_post_meta( $post_id, '_wpbp_isbn', sanitize_text_field( wp_unslash( $_POST['wpbp_isbn'] ) ) );
    }
);

add_filter(
    'bulk_actions-edit-wpbp_book',
    static function ( $actions ) {
        $actions['wpbp_archive'] = 'Archive';

        return $actions;
    }
);

add_filter(
    'handle_bulk_actions-edit-wpbp_book',
    static function ( $redirect_to, $doaction, $post_ids ) {
        if ( 'wpbp_archive' !== $doaction ) {
            return $redirect_to;
        }

        $archived = 0;

        foreach ( (array) $post_ids as $post_id ) {
            if ( ! current_user_can( 'edit_post', $post_id ) ) {
                continue;
            }

            update_post_meta( $post_id, 'wpbp_archived', 1 );
            ++$archived;
        }

        return add_query_arg( 'wpbp_archived', $archived, $redirect_to );
    },
    10,
    3
);

add_action(
    'admin_post_wpbp_save_note',
    static function () {
        $nonce = isset( $_POST['wpbp_note_nonce'] ) ? sanitize_text_field( wp_unslash( $_POST['wpbp_note_nonce'] ) ) : '';

        if ( ! wp_verify_nonce( $nonce, 'wpbp_save_note' ) ) {
            wp_die( 'Invalid request.', '', array( 'response' => 403 ) );
        }

        if ( ! current_user_can( 'manage_options' ) ) {
            wp_die( 'Not allowed.', '', array( 'response' => 403 ) );
        }

        $note = isset( $_POST['wpbp_note'] ) ? sanitize_text_field( wp_unslash( $_POST['wpbp_note'] ) ) : '';

        update_option( 'wpbp_note', $note );

        wp_safe_redirect( add_query_arg( 'wpbp_saved', 1, admin_url( 'options-general.php' ) ) );
        exit;
    }
);

add_filter(
    'site_status_tests',
    static function ( $tests ) {
        $tests['direct']['wpbp_backup_freshness'] = array(
            'label' => 'Backup freshness',
            'test'  => static function () {
                $last   = (int) get_option( 'wpbp_last_backup', 0 );
                $recent = $last > 0 && ( time() - $last ) < WEEK_IN_SECONDS;

                return array(
                    'label'       => $recent ? 'Your last backup is recent' : 'Your last backup is out of date',
                    'status'      => $recent ? 'good' : 'recommended',
                    'badge'       => array(
                        'label' => 'Security',
                        'color' => $recent ? 'blue' : 'orange',
                    ),
                    'description' => '<p>' . ( $recent ? 'A backup ran within the last seven days.' : 'No backup has been recorded in the last seven days.' ) . '</p>',
                    'actions'     => '',
                    'test'        => 'wpbp_backup_freshness',
                );
            },
        );

        return $tests;
    }
);

function wpbp_admin_009( array $notice ): string {
    return wp_get_admin_notice(
        esc_html( (string) $notice['text'] ),
        array(
            'type'               => (string) $notice['level'],
            'dismissible'        => empty( $notice['sticky'] ),
            'id'                 => 'wpbp-notice-' . $notice['slug'],
            'additional_classes' => array( 'wpbp-notice' ),
        )
    );
}

add_action(
    'wp_dashboard_setup',
    static function () {
        if ( ! current_user_can( 'moderate_comments' ) ) {
            return;
        }

        wp_add_dashboard_widget(
            'wpbp_pending_reviews',
            'Pending Reviews',
            static function () {
                $counts = wp_count_comments();

                printf(
                    '<p>Comments awaiting moderation: %s</p>',
                    esc_html( (string) (int) $counts->moderated )
                );
            }
        );
    }
);

$GLOBALS['wpbp_panel_hook'] = '';

add_action(
    'admin_menu',
    static function () {
        $GLOBALS['wpbp_panel_hook'] = add_menu_page(
            'WPBP Panel',
            'WPBP Panel',
            'manage_options',
            'wpbp-panel',
            '__return_null'
        );
    }
);

add_action(
    'admin_enqueue_scripts',
    static function ( $hook_suffix ) {
        if ( $hook_suffix !== $GLOBALS['wpbp_panel_hook'] ) {
            return;
        }

        wp_enqueue_script(
            'wpbp-panel',
            content_url( 'wpbp-panel.js' ),
            array( 'jquery' ),
            '1.0.0',
            true
        );
    }
);

add_filter(
    'plugin_action_links_wpbp-demo/wpbp-demo.php',
    static function ( $actions ) {
        $settings = sprintf(
            '<a href="%s">%s</a>',
            esc_url( admin_url( 'options-general.php?page=wpbp-demo' ) ),
            'Settings'
        );

        return array_merge( array( 'wpbp_settings' => $settings ), (array) $actions );
    }
);

add_filter(
    'plugin_row_meta',
    static function ( $meta, $plugin_file ) {
        if ( 'wpbp-demo/wpbp-demo.php' !== $plugin_file ) {
            return $meta;
        }

        $meta[] = sprintf(
            '<a href="%s">%s</a>',
            esc_url( 'https://example.org/wpbp-docs' ),
            'Docs'
        );

        return $meta;
    },
    10,
    2
);
